// Package agentctx lowers a repository index into bounded, readable evidence
// for an agent. The index is an internal planning representation; a Bundle is a
// self-contained tool-result payload. Source text is always untrusted data.
package agentctx

import "github.com/tdeshazo/repoctx/pkg/ir"

const Version = "repoctx.context/v1alpha3"

// TokenCounter must count the exact supplied rendered bytes using the target
// model's tokenizer. No generic chars/token estimate is used as a token bound.
type TokenCounter func([]byte) (int, error)

type Options struct {
	Root             string
	Query            string
	Symbols          []string      // exact semantic IDs, never persistent dense IDs
	Units            []string      // snapshot-bound retrieval unit IDs
	MaxUnits         int           // default 8; at most 64
	ExpectedSnapshot string        // optional sha256: index digest, for expansion/replay
	Depth            int           // 0 = seeds only; at most 4
	Direction        string        // out, in, both (default)
	Relations        []ir.EdgeKind // default: calls, defines; imports rendered as evidence
	MaxSymbols       int           // default 12; at most 64
	MaxCandidates    int           // default 128; at most 4096
	MaxRelations     int           // default 48
	MaxBytes         int           // exact serialized payload cap; default 32768
	Format           string        // json (default) or markdown
	AllowPaths       []string      // explicit scope must match compilation; omitted scope inherits index policy
	DenyPaths        []string      // deny wins; explicit scope must match compilation
	MaxSourceBytes   int64         // per-file bound; default 2 MiB
	MaxReadBytes     int64         // total verified source bytes; default 256 MiB
	MaxTokens        int           // optional exact payload token cap; requires CountTokens
	CountTokens      TokenCounter
	TokenizerID      string // caller-owned implementation/version identity when CountTokens is set
	Consistency      string // verified-local (default) or immutable; immutable requires ExpectedSnapshot
	sourceMode       string // internal provenance discriminator for deterministic task identities
	authorityScope   string // internal caller-owned scope discriminator; never rendered
}

type Bundle struct {
	Version       string         `json:"version"`
	TaskID        string         `json:"task_id"`
	Snapshot      Snapshot       `json:"snapshot"`
	Query         string         `json:"query,omitempty"`
	Seeds         []string       `json:"seeds"`
	Trust         Trust          `json:"trust"`
	Capabilities  Capabilities   `json:"capabilities"`
	Selection     Selection      `json:"selection"`
	Symbols       []Symbol       `json:"symbols"`
	Units         []Unit         `json:"units"`
	Evidence      []Evidence     `json:"evidence"`
	Relationships []Relationship `json:"relationships,omitempty"`
	Omissions     Omissions      `json:"omissions"`
	Warnings      []string       `json:"warnings"`
}

type Snapshot struct {
	ID            string `json:"id"`
	IRVersion     string `json:"ir_version"`
	Verification  string `json:"verification"`
	VerifiedFiles int    `json:"verified_files"`
	SourceID      string `json:"source_id"`
	ProfileID     string `json:"profile_id"`
}
type Trust struct {
	Role     string `json:"role"`
	Handling string `json:"handling"`
}
type Capabilities struct {
	Available      []string `json:"available"`
	Unavailable    []string `json:"unavailable"`
	CallResolution string   `json:"call_resolution"`
	Verification   string   `json:"verification"`
}
type Selection struct {
	Strategy      string   `json:"strategy"`
	Depth         int      `json:"depth"`
	Direction     string   `json:"direction"`
	Relations     []string `json:"relations"`
	MaxBytes      int      `json:"max_bytes"`
	MaxTokens     int      `json:"max_tokens,omitempty"`
	MaxSymbols    int      `json:"max_symbols"`
	MaxCandidates int      `json:"max_candidates"`
	MaxRelations  int      `json:"max_relations"`
	MaxUnits      int      `json:"max_units"`
}
type Span struct {
	StartLine       int `json:"start_line"`
	StartByteColumn int `json:"start_byte_column"`
	EndLine         int `json:"end_line"`
	EndByteColumn   int `json:"end_byte_column"`
}

func span(x ir.Span) Span { return Span{x.SL, x.SC, x.EL, x.EC} }

type Reason struct {
	Strategy      string         `json:"strategy"`
	Depth         int            `json:"depth"`
	Score         int            `json:"score"` // ranking signal, not probability or confidence
	Via           string         `json:"via,omitempty"`
	Relation      string         `json:"relation,omitempty"`
	Direction     string         `json:"direction,omitempty"`
	MatchedFields []string       `json:"matched_fields,omitempty"`
	Components    map[string]int `json:"components,omitempty"`
}

// Unit is a source-backed retrieval extent, separate from a symbol definition.
// Parent identifies a containing unit in the same snapshot, not necessarily
// selected in this bundle. Evidence may be several noncontiguous exact spans.
type Unit struct {
	ID           string   `json:"id"`
	Kind         string   `json:"kind"`
	File         string   `json:"file"`
	Parent       string   `json:"parent,omitempty"`
	Extent       Span     `json:"extent"`
	Heading      *Span    `json:"heading,omitempty"`
	Content      *Span    `json:"content,omitempty"` // section body, excluding its heading
	Evidence     []string `json:"evidence"`
	Completeness string   `json:"completeness"`
	Reason       Reason   `json:"reason"`
}
type Symbol struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	Kind         string `json:"kind"`
	Language     string `json:"language"`
	File         string `json:"file"`
	Unit         string `json:"unit,omitempty"`
	Definition   Span   `json:"definition"`
	Evidence     string `json:"evidence"`     // evidence ID; may be shared with another symbol
	Completeness string `json:"completeness"` // full_definition or declaration_excerpt
	Reason       Reason `json:"reason"`
}
type Evidence struct {
	ID        string `json:"id"`
	File      string `json:"file"`
	SHA256    string `json:"sha256"`
	Span      Span   `json:"span"`
	StartByte int    `json:"start_byte"`
	EndByte   int    `json:"end_byte"`
	Role      string `json:"role"` // source or imports; always untrusted repository data
	Text      string `json:"text"`
}
type Location struct {
	File   string `json:"file"`
	Span   Span   `json:"span"`
	SHA256 string `json:"sha256"`
}
type Relationship struct {
	From        string     `json:"from"`
	To          string     `json:"to"`
	Kind        string     `json:"kind"`
	Resolution  string     `json:"resolution"` // syntactic, name_heuristic, unresolved
	Occurrences uint32     `json:"occurrences"`
	Sites       []Location `json:"sites,omitempty"` // up to three source occurrences
}
type Omissions struct {
	Candidates       int  `json:"candidates"`
	Budget           int  `json:"budget"`
	SymbolLimit      int  `json:"symbol_limit"`
	Excerpts         int  `json:"excerpts"`
	Relations        int  `json:"relations"`
	Imports          int  `json:"imports"`
	TraversalLimited bool `json:"traversal_limited"`
	UnitLimit        int  `json:"unit_limit"`
}
type Usage struct {
	Bytes       int    `json:"bytes"`
	Tokens      int    `json:"tokens"`
	TokenMethod string `json:"token_method"`
	ExactTokens bool   `json:"exact_tokens"`
}
type Result struct {
	Bundle  *Bundle
	Payload []byte // includes final newline; write these bytes without re-encoding
	Usage   Usage
}
package agentctx

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"unicode"

	"github.com/tdeshazo/repoctx/pkg/ir"
)

type candidate struct {
	node   int
	reason Reason
	seed   bool
	unit   *retrievalUnit
}

func terms(s string) []string {
	var out []string
	var word []rune
	var prev rune
	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) {
			if len(word) > 0 {
				out = append(out, strings.ToLower(string(word)))
				word = nil
			}
		} else {
			if unicode.IsUpper(r) && unicode.IsLower(prev) && len(word) > 0 {
				out = append(out, strings.ToLower(string(word)))
				word = nil
			}
			word = append(word, r)
		}
		prev = r
	}
	if len(word) > 0 {
		out = append(out, strings.ToLower(string(word)))
	}
	stop := map[string]bool{"a": true, "an": true, "the": true, "to": true, "in": true, "of": true, "for": true, "and": true, "fix": true, "change": true, "how": true, "does": true, "is": true}
	seen := map[string]bool{}
	var clean []string
	for _, x := range out {
		if !stop[x] && !seen[x] {
			seen[x] = true
			clean = append(clean, x)
		}
	}
	return clean
}
func chooseSymbols(ctx context.Context, r *ir.Repository, o Options, sources map[int]*source) ([]candidate, []string, bool, error) {
	var seeds []candidate
	byID := map[string]int{}
	for i, s := range r.Symbols {
		if i&255 == 0 {
			if err := ctx.Err(); err != nil {
				return nil, nil, false, err
			}
		}
		if sources[s.File] != nil {
			byID[r.String(s.ID)] = i
		}
	}
	if len(o.Symbols) > 0 {
		seen := map[int]bool{}
		for _, id := range o.Symbols {
			i, ok := byID[id]
			if !ok {
				return nil, nil, false, fmt.Errorf("requested symbol not found in permitted index: %q", id)
			}
			if !seen[i] {
				seen[i] = true
				seeds = append(seeds, candidate{node: i, reason: Reason{Strategy: "explicit_symbol", Score: 100000}, seed: true})
			}
		}
	} else if len(o.Units) == 0 {
		words := terms(o.Query)
		var ranked []candidate
		for i, s := range r.Symbols {
			if i&255 == 0 {
				if err := ctx.Err(); err != nil {
					return nil, nil, false, err
				}
			}
			if sources[s.File] == nil {
				continue
			}
			id := r.String(s.ID)
			name := strings.ToLower(r.String(s.Name))
			qualified := strings.ToLower(id)
			p := strings.ToLower(r.String(r.Files[s.File].Path))
			exactScore, nameScore, idScore, pathScore := 0, 0, 0, 0
			q := strings.ToLower(strings.TrimSpace(o.Query))
			if q == name || q == qualified {
				exactScore = 10000
			}
			for _, t := range words {
				if t == name {
					nameScore += 100
				} else if strings.Contains(name, t) {
					nameScore += 50
				}
				if strings.Contains(qualified, t) {
					idScore += 20
				}
				if strings.Contains(p, t) {
					pathScore += 5
				}
			}
			bodyScore := 0
			if r.Files[s.File].Lang != ir.LangMarkdown {
				a, z, err := sources[s.File].offsets(r.Files[s.File].Nodes[s.Node].Span)
				if err != nil {
					return nil, nil, false, err
				}
				body := strings.ToLower(string(sources[s.File].data[a:z]))
				for _, word := range words {
					if strings.Contains(body, word) {
						bodyScore += 30
					}
				}
			}
			score := exactScore + nameScore + idScore + pathScore + bodyScore
			if score > 0 {
				fields := []string{}
				if nameScore > 0 || q == name {
					fields = append(fields, "name")
				}
				if idScore > 0 || q == qualified {
					fields = append(fields, "semantic_id")
				}
				if pathScore > 0 {
					fields = append(fields, "path")
				}
				if bodyScore > 0 {
					fields = append(fields, "body")
				}
				ranked = append(ranked, candidate{node: i, reason: Reason{Strategy: "lexical_seed", Score: score,
					MatchedFields: fields, Components: map[string]int{"exact": exactScore, "name": nameScore,
						"semantic_id": idScore, "path": pathScore, "body": bodyScore}}, seed: true})
			}
		}
		sort.Slice(ranked, func(i, j int) bool {
			if ranked[i].reason.Score != ranked[j].reason.Score {
				return ranked[i].reason.Score > ranked[j].reason.Score
			}
			return r.String(r.Symbols[ranked[i].node].ID) < r.String(r.Symbols[ranked[j].node].ID)
		})
		if len(ranked) > 0 {
			threshold := ranked[0].reason.Score / 2
			for _, c := range ranked {
				if len(seeds) >= 3 || len(seeds) >= o.MaxSymbols || len(seeds) >= o.MaxCandidates || c.reason.Score < threshold {
					break
				}
				seeds = append(seeds, c)
			}
		}
	}
	if len(seeds) == 0 {
		return nil, nil, false, nil
	}
	if len(seeds) > o.MaxSymbols || len(seeds) > o.MaxCandidates {
		return nil, nil, false, fmt.Errorf("seed count exceeds symbol/candidate limit")
	}
	wanted := map[ir.EdgeKind]bool{}
	for _, k := range o.Relations {
		wanted[k] = true
	}
	selected := map[int]candidate{}
	var queue []int
	var ids []string
	for _, c := range seeds {
		selected[c.node] = c
		queue = append(queue, c.node)
		ids = append(ids, r.String(r.Symbols[c.node].ID))
	}
	limited := false
	scanned := 0
	if r.Graph != nil {
		for q := 0; q < len(queue); q++ {
			cur := selected[queue[q]]
			if cur.reason.Depth >= o.Depth {
				continue
			}
			type direction struct {
				name string
				csr  ir.CSR
			}
			dirs := []direction{}
			if o.Direction != "in" {
				dirs = append(dirs, direction{"out", r.Graph.Out})
			}
			if o.Direction != "out" {
				dirs = append(dirs, direction{"in", r.Graph.In})
			}
			for _, d := range dirs {
				for j := d.csr.Offsets[cur.node]; j < d.csr.Offsets[cur.node+1]; j++ {
					scanned++
					if scanned&255 == 0 {
						if err := ctx.Err(); err != nil {
							return nil, nil, false, err
						}
					}
					if scanned > 100000 {
						limited = true
						break
					}
					n := int(d.csr.Targets[j])
					k := d.csr.Kinds[j]
					// Do not traverse unit hubs or globally merged unresolved names. Such
					// expansion creates spurious relationships between unrelated packages.
					if n >= len(r.Symbols) || !wanted[k] || sources[r.Symbols[n].File] == nil {
						continue
					}
					if _, ok := selected[n]; ok {
						continue
					}
					if len(selected) >= o.MaxCandidates {
						limited = true
						continue
					}
					next := candidate{node: n, reason: Reason{Strategy: "graph_neighbor", Depth: cur.reason.Depth + 1, Score: cur.reason.Score / 2, Via: r.String(r.Symbols[cur.node].ID), Relation: edgeName(k), Direction: d.name}}
					selected[n] = next
					queue = append(queue, n)
				}
				if scanned > 100000 {
					break
				}
			}
			if scanned > 100000 {
				break
			}
		}
	}
	var rest []candidate
	for _, c := range selected {
		if !c.seed {
			rest = append(rest, c)
		}
	}
	sort.Slice(rest, func(i, j int) bool {
		a, b := rest[i], rest[j]
		if a.reason.Depth != b.reason.Depth {
			return a.reason.Depth < b.reason.Depth
		}
		if a.reason.Score != b.reason.Score {
			return a.reason.Score > b.reason.Score
		}
		return r.String(r.Symbols[a.node].ID) < r.String(r.Symbols[b.node].ID)
	})
	return append(seeds, rest...), ids, limited, nil
}
func edgeName(k ir.EdgeKind) string {
	return map[ir.EdgeKind]string{ir.EdgeDefines: "defines", ir.EdgeCalls: "calls", ir.EdgeImports: "imports", ir.EdgeReferences: "references"}[k]
}
func kindName(k ir.SymbolKind) string {
	return map[ir.SymbolKind]string{ir.SymModule: "module", ir.SymType: "type", ir.SymFunction: "function", ir.SymMethod: "method", ir.SymVariable: "variable", ir.SymConstant: "constant"}[k]
}
func languageName(k ir.Language) string {
	switch k {
	case ir.LangGo:
		return "go"
	case ir.LangPython:
		return "python"
	case ir.LangHTML:
		return "html"
	case ir.LangCSS:
		return "css"
	case ir.LangJavaScript:
		return "javascript"
	case ir.LangTypeScript:
		return "typescript"
	case ir.LangTSX:
		return "tsx"
	case ir.LangMarkdown:
		return "markdown"
	default:
		return "unknown"
	}
}
package agentctx

import (
	"path/filepath"
	"sort"
	"strings"

	"github.com/tdeshazo/repoctx/pkg/ir"
)

func graphLabel(r *ir.Repository, n int) string {
	if n < len(r.Symbols) {
		return r.String(r.Symbols[n].ID)
	}
	return r.String(r.Graph.External[n-len(r.Symbols)].Name)
}

func relationships(r *ir.Repository, b *Bundle, sources map[int]*source, limit int) ([]Relationship, int) {
	if r.Graph == nil {
		return nil, 0
	}
	selected := map[int]bool{}
	ids := map[string]bool{}
	for _, s := range b.Symbols {
		ids[s.ID] = true
	}
	for i, s := range r.Symbols {
		if ids[r.String(s.ID)] {
			selected[i] = true
		}
	}
	type arc struct {
		from, to int
		kind     ir.EdgeKind
		weight   uint32
	}
	type key struct {
		from, to int
		kind     ir.EdgeKind
	}
	seen := map[key]bool{}
	var arcs []arc
	permitted := func(n int) bool { return n >= len(r.Symbols) || sources[r.Symbols[n].File] != nil }
	add := func(from, to int, k ir.EdgeKind, w uint32) {
		a := key{from, to, k}
		if seen[a] || !permitted(from) || !permitted(to) {
			return
		}
		seen[a] = true
		arcs = append(arcs, arc{from, to, k, w})
	}
	nodes := make([]int, 0, len(selected))
	for n := range selected {
		nodes = append(nodes, n)
	}
	sort.Ints(nodes)
	// Only adjacent arcs, not a graph dump. External/unit nodes are named
	// boundaries; their neighborhoods are not traversed.
	for _, n := range nodes {
		c := r.Graph.Out
		for j := c.Offsets[n]; j < c.Offsets[n+1]; j++ {
			add(n, int(c.Targets[j]), c.Kinds[j], c.Weights[j])
		}
		c = r.Graph.In
		for j := c.Offsets[n]; j < c.Offsets[n+1]; j++ {
			add(int(c.Targets[j]), n, c.Kinds[j], c.Weights[j])
		}
	}
	sort.Slice(arcs, func(i, j int) bool {
		a, z := arcs[i], arcs[j]
		ac, zc := 0, 0
		if selected[a.from] && selected[a.to] {
			ac = 1
		}
		if selected[z.from] && selected[z.to] {
			zc = 1
		}
		if ac != zc {
			return ac > zc
		}
		af, zf := graphLabel(r, a.from), graphLabel(r, z.from)
		if af != zf {
			return af < zf
		}
		at, zt := graphLabel(r, a.to), graphLabel(r, z.to)
		if at != zt {
			return at < zt
		}
		return a.kind < z.kind
	})
	omitted := 0
	if len(arcs) > limit {
		omitted = len(arcs) - limit
		arcs = arcs[:limit]
	}
	var out []Relationship
	for _, a := range arcs {
		rel := Relationship{From: graphLabel(r, a.from), To: graphLabel(r, a.to), Kind: edgeName(a.kind), Occurrences: a.weight, Resolution: "syntactic"}
		if a.kind == ir.EdgeCalls || a.kind == ir.EdgeReferences {
			rel.Resolution = "name_heuristic"
			if a.to >= len(r.Symbols) {
				rel.Resolution = "unresolved"
			}
		}
		if a.kind == ir.EdgeDefines && a.to < len(r.Symbols) {
			s := r.Symbols[a.to]
			f := r.Files[s.File]
			rel.Sites = []Location{{File: r.String(f.Path), Span: span(f.Nodes[s.Node].Span), SHA256: f.Hash}}
		} else {
			for _, e := range r.Edges {
				if len(rel.Sites) >= 3 {
					break
				}
				if e.Kind != a.kind || sources[e.From.File] == nil {
					continue
				}
				if a.from < len(r.Symbols) && e.OwnerSymbol != a.from+1 {
					continue
				}
				if a.from >= len(r.Symbols) {
					if e.OwnerSymbol != 0 {
						continue
					}
					f := r.Files[e.From.File]
					unit := r.String(f.Unit)
					label := "unit:py:" + unit
					if f.Lang == ir.LangGo {
						dir := filepath.ToSlash(filepath.Dir(r.String(f.Path)))
						if dir != "." {
							unit = dir + "/" + unit
						}
						label = "unit:go:" + unit
					} else if f.Lang != ir.LangPython {
						label = "unit:" + r.String(f.Path)
					}
					if label != rel.From {
						continue
					}
				}
				matches := e.ToSymbol > 0 && e.ToSymbol-1 == a.to
				if e.ToSymbol == 0 && a.to >= len(r.Symbols) {
					x := r.Graph.External[a.to-len(r.Symbols)]
					label := r.String(x.Name)
					// Unresolved calls use a symbol:<name> external label,
					// while imports point at either a repository unit or an
					// external module. Keep the occurrence site attached to
					// all three boundary forms.
					switch a.kind {
					case ir.EdgeImports:
						raw := r.String(e.Text)
						matches = label == "module:"+raw
						if !matches && x.Kind == ir.GraphExternalUnit {
							matches = importUnitMatches(r, e, label, raw)
							if !matches {
								// Retain a conservative fallback for an older index whose
								// graph label cannot expose enough module information.
								matches = importArcTargets(r, e, a.to)
							}
						}
					default:
						matches = label == "symbol:"+r.String(e.Text)
					}
				}
				if !matches {
					continue
				}
				f := r.Files[e.From.File]
				rel.Sites = append(rel.Sites, Location{File: r.String(f.Path), Span: span(f.Nodes[e.From.Node].Span), SHA256: f.Hash})
			}
		}
		out = append(out, rel)
	}
	return out, omitted
}

func importUnitMatches(r *ir.Repository, e ir.Edge, label, raw string) bool {
	if e.From.File < 0 || e.From.File >= len(r.Files) {
		return false
	}
	source := r.Files[e.From.File]
	if source.Lang == ir.LangPython {
		return label == "unit:py:"+raw || strings.HasPrefix(raw, strings.TrimPrefix(label, "unit:py:")+".")
	}
	if source.Lang != ir.LangGo || !strings.HasPrefix(label, "unit:go:") {
		return false
	}
	// Current Go unit labels are unit:go:<relative-directory>/<package>.
	// The module prefix from go.mod is absent from that label, so compare the
	// relative-directory suffix of the import path. This distinguishes ordinary
	// repository imports without pretending to implement module resolution.
	key := strings.TrimPrefix(label, "unit:go:")
	dir := ""
	if slash := strings.LastIndexByte(key, '/'); slash >= 0 {
		dir = key[:slash]
	}
	if dir == "" {
		return !strings.Contains(raw, "/")
	}
	return strings.HasSuffix(raw, "/"+dir)
}

func importArcTargets(r *ir.Repository, e ir.Edge, target int) bool {
	from := -1
	if e.OwnerSymbol > 0 {
		from = e.OwnerSymbol - 1
	} else if unit := graphUnitForFile(r, e.From.File); unit >= 0 {
		from = unit
	}
	if from < 0 || from+1 >= len(r.Graph.Out.Offsets) {
		return false
	}
	for i := r.Graph.Out.Offsets[from]; i < r.Graph.Out.Offsets[from+1]; i++ {
		if r.Graph.Out.Kinds[i] == ir.EdgeImports && int(r.Graph.Out.Targets[i]) == target {
			return true
		}
	}
	return false
}

// graphUnitForFile returns the external unit node used as an occurrence's
// source when it is not owned by a symbol. Labels are derived exactly as in
// compiler.buildSymbolGraph; no additional module-resolution claim is made.
func graphUnitForFile(r *ir.Repository, file int) int {
	if file < 0 || file >= len(r.Files) {
		return -1
	}
	f := r.Files[file]
	path := filepath.ToSlash(r.String(f.Path))
	unit := r.String(f.Unit)
	label := ""
	switch f.Lang {
	case ir.LangGo:
		dir := filepath.ToSlash(filepath.Dir(path))
		if dir == "." {
			dir = ""
		}
		if dir != "" {
			unit = dir + "/" + unit
		}
		label = "unit:go:" + unit
	case ir.LangPython:
		label = "unit:py:" + unit
	default:
		label = "unit:" + path
	}
	for i, x := range r.Graph.External {
		if x.Kind == ir.GraphExternalUnit && r.String(x.Name) == label {
			return len(r.Symbols) + i
		}
	}
	return -1
}

package cli

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/tdeshazo/repoctx/pkg/agentctx"
	"github.com/tdeshazo/repoctx/pkg/compiler"
