264			if src == nil || !chosenFiles[src.path] {
265				continue
266			}
267			sp := f.Nodes[edge.From.Node].Span
268			if f.Lang == ir.LangGo {
269				for _, n := range f.Nodes {
270					if r.String(n.Kind) == "GenDecl" && contains(n.Span, sp) {
271						sp = n.Span
272						break
273					}
274				}
275			}
276			a, z, e := src.offsets(sp)
277			if e != nil {
278				return nil, fmt.Errorf("import span: %w", e)
279			}
280			key := evidenceID(src, a, z)
281			if seenImports[key] {
282				continue
283			}
284			seenImports[key] = true
285			trial := clone(b)
286			addEvidence(trial, src, a, z, "imports")
287			ok, e := fits(trial, importBudget, true)
288			if e != nil {
289				return nil, e
290			}
291			if ok {
292				b = trial
293			} else {
294				b.Omissions.Imports++
295			}
296		}
297		markPartialQueryExcerpts(b, sources)
298		if e := ctx.Err(); e != nil {
299			return nil, e
300		}
301		rels, omittedRelations := relationships(r, b, sources, o.MaxRelations)
302		b.Omissions.Relations += omittedRelations
303		for _, rel := range rels {
304			if e := ctx.Err(); e != nil {
305				return nil, e
306			}
307			if len(b.Relationships) >= o.MaxRelations {
308				b.Omissions.Relations++
309				continue
310			}
311			trial := clone(b)
312			trial.Relationships = append(trial.Relationships, rel)
313			ok, e := fits(trial, o, true)
314			if e != nil {
315				return nil, e
316			}
317			if ok {
318				b = trial
319			} else {
320				b.Omissions.Relations++
321			}
322		}
323		// Recheck after all counters and metadata are finalized. Never truncate JSON
324		// or code to force a fit; failure returns no partial payload.
325		p, e := Render(b, o.Format)
326		if e != nil {
327			return nil, e
328		}
329		u, e := measure(p, o)
330		if e != nil {
331			return nil, e
332		}
333		if u.Bytes > o.MaxBytes || (o.MaxTokens > 0 && u.Tokens > o.MaxTokens) {
334			return nil, fmt.Errorf("final payload exceeds budget; increase budget or narrow context")
335		}
336		if e := b.Validate(); e != nil {
337			return nil, fmt.Errorf("bundle invariant: %w", e)
338		}
339		return &Result{Bundle: b, Payload: p, Usage: u}, nil
340	}
