402		}
403		if o.MaxBytes < 1 || o.MaxBytes > 8<<20 {
404			return fmt.Errorf("max bytes must be 1..8388608")
405		}
406		if o.MaxSymbols == 0 {
407			o.MaxSymbols = 12
408		}
409		if o.MaxSymbols < 1 || o.MaxSymbols > 64 {
410			return fmt.Errorf("max symbols must be 1..64")
411		}
412		if o.MaxCandidates == 0 {
413			o.MaxCandidates = 128
414		}
415		if o.MaxCandidates < 1 || o.MaxCandidates > 4096 {
416			return fmt.Errorf("max candidates must be 1..4096")
417		}
418		if o.MaxRelations == 0 {
419			o.MaxRelations = 48
420		}
421		if o.MaxRelations < 1 || o.MaxRelations > 256 {
422			return fmt.Errorf("max relations must be 1..256")
423		}
424		if o.Depth < 0 || o.Depth > 4 {
425			return fmt.Errorf("depth must be 0..4")
426		}
427		if o.Direction == "" {
428			o.Direction = "both"
429		}
430		if o.Direction != "in" && o.Direction != "out" && o.Direction != "both" {
431			return fmt.Errorf("direction must be in, out or both")
432		}
433		if len(o.Relations) == 0 {
434			o.Relations = []ir.EdgeKind{ir.EdgeCalls, ir.EdgeDefines}
435		}
436		for _, k := range o.Relations {
437			if k != ir.EdgeCalls && k != ir.EdgeDefines && k != ir.EdgeImports {
438				return fmt.Errorf("unsupported traversal relation %d; REFERENCES is not implemented", k)
439			}
440		}
441		if o.Format == "" {
442			o.Format = "json"
443		}
444		if o.Format != "json" && o.Format != "markdown" {
445			return fmt.Errorf("format must be json or markdown")
446		}
447		if o.MaxSourceBytes == 0 {
448			o.MaxSourceBytes = 2 << 20
449		}
450		if o.MaxReadBytes == 0 {
451			o.MaxReadBytes = 256 << 20
452		}
453		if o.MaxSourceBytes < 1 || o.MaxReadBytes < 1 {
454			return fmt.Errorf("source read limits must be positive")
455		}
456		if o.MaxTokens < 0 || o.MaxTokens > 0 && o.CountTokens == nil {
457			return fmt.Errorf("a token budget requires a caller-supplied model tokenizer; byte/4 is not a token bound")
458		}
459		return validatePrefixes(*o)
