465	// Validate checks cross-references in a bundle. It does not authenticate source
466	// bytes; Build additionally compares each served file against the index hash.
467	func (b *Bundle) Validate() error {
468		if b.Version != Version {
469			return fmt.Errorf("unsupported context version")
470		}
471		for _, id := range []string{b.TaskID, b.Snapshot.ID, b.Snapshot.SourceID, b.Snapshot.ProfileID} {
472			hash, err := hex.DecodeString(strings.TrimPrefix(id, "sha256:"))
473			if !strings.HasPrefix(id, "sha256:") || err != nil || len(hash) != 32 {
474				return fmt.Errorf("invalid context identity")
475			}
235			}
