237		var rest []candidate
238		for _, c := range selected {
239			if !c.seed {
240				rest = append(rest, c)
241			}
242		}
243		sort.Slice(rest, func(i, j int) bool {
244			a, b := rest[i], rest[j]
245			if a.reason.Depth != b.reason.Depth {
246				return a.reason.Depth < b.reason.Depth
247			}
248			if a.reason.Score != b.reason.Score {
249				return a.reason.Score > b.reason.Score
250			}
251			return r.String(r.Symbols[a.node].ID) < r.String(r.Symbols[b.node].ID)
252		})
253		return append(seeds, rest...), ids, limited, nil
254	}
